        <script>
           let loginInWithRecoveryCode = document.getElementById('login_with_recovery_code');
            let loginInWithCode = document.getElementById('login_with_code');

            let recoveryCodeElem = document.getElementById('recovery_code');
            let codeElem = document.getElementById('code');

            let recoveryCodeLabel = document.getElementById('recovery_code_label');
            let codeLabel = document.getElementById('code_label')

            let form = document.getElementById('two_factor_form');

            let codeUrl = "{{url('/two-factor-challenge')}}"
            let recoveryCodeUrl = "{{url('user/two-factor-recovery-codes')}}"

            // user/two-factor-recovery-codes

            loginInWithRecoveryCode.addEventListener('click', function(event) {
                event.preventDefault();

                // Show the recovery code input and switch buttons
                recoveryCodeElem.classList.remove('hidden');
                recoveryCodeElem.classList.add('show');

                // Show the code input
                codeElem.classList.remove('show');
                codeElem.classList.add('hidden');

                loginInWithCode.classList.remove('hidden');
                loginInWithCode.classList.add('show');

                codeLabel.classList.add('hidden')
                recoveryCodeLabel.classList.add('show')
                recoveryCodeLabel.classList.remove('hidden')

                // Hide the current element (loginInWithRecoveryCode button)
                this.classList.add('hidden');
                form.setAttribute('action', codeUrl)

            });

            loginInWithCode.addEventListener('click', function(event) {
                event.preventDefault();

                // Show the recovery code input and switch buttons
                recoveryCodeElem.classList.remove('show');
                recoveryCodeElem.classList.add('hidden');

                // Show the code input
                codeElem.classList.remove('hidden');
                codeElem.classList.add('show');

                loginInWithRecoveryCode.classList.remove('hidden');
                loginInWithRecoveryCode.classList.add('show');

                recoveryCodeLabel.classList.add('hidden')
                codeLabel.classList.add('show')
                codeLabel.classList.remove('hidden')


                // Hide the current element (loginInWithRecoveryCode button)
                this.classList.add('hidden');
                form.setAttribute('action', recoveryCodeUrl)
            });

        </script>
